"""The country parts of the legal notice in Polish (Poland's own is in ``jurisdictions``)."""

SECTIONS: dict[str, str] = {
    "JP": """Japonia. Prawo autorskie: art. 30 ust. 1 ustawy o prawie autorskim pozwala zwielokrotniać utwór na użytek osobisty lub rodzinny, a art. 47-6 pozwala go w tym celu tłumaczyć; pokazywanie lub przekazywanie kopii albo tłumaczenia komukolwiek innemu stanowi naruszenie (art. 49). Wyjątek nie obejmuje kopii sporządzonych przez obejście zabezpieczenia (art. 30 ust. 1 pkt 2); TASlation przechwytuje to, co czytnik już wyświetlił, i nie obchodzi żadnego zabezpieczenia; przechwycony obraz pozostaje w pamięci i jest co najwyżej incydentalnym zwielokrotnieniem przy przetwarzaniu komputerowym, na co zezwala art. 47-4. Regulamin Twojej księgarni internetowej może jednak tego zabraniać. Treści: posiadanie seksualnych wizerunków rzeczywistych dzieci jest przestępstwem od nowelizacji ustawy o pornografii dziecięcej z 2014 r.; rysunki nie są objęte tą ustawą. Przestępstwo dotyczące treści obscenicznych z art. 175 kodeksu karnego polega na rozpowszechnianiu i posiadaniu w celu sprzedaży, a nie na prywatnym posiadaniu, więc mangę sprzedawaną w Japonii można tu legalnie posiadać. Kraj, do którego zabierzesz swój czytnik, może oceniać to wszystko inaczej.""",
    "GB": """Wielka Brytania. Prawo autorskie: nie ma wyjątku dla kopii prywatnej. Wyjątek wprowadzony w 2014 r. (sekcja 28B ustawy Copyright, Designs and Patents Act) został w 2015 r. unieważniony przez Wysoki Trybunał (High Court), a tłumaczenie na własny użytek jest opracowaniem, którego nie obejmuje żaden wyjątek; fair dealing służy badaniom, prywatnej nauce, krytyce i podobnym celom, a nie czytaniu dla przyjemności. Tłumaczenie na własny użytek stanowi zatem w świetle prawa naruszenie (samo przechwycenie ekranu jest kopią przejściową, jaką obejmuje wyjątek dla kopii tymczasowych), ale o charakterze cywilnoprawnym: bez obrotu handlowego lub rozpowszechniania nie ma przestępstwa, a prywatnego użytku bez udostępniania nigdy nie ścigano. Treści: posiadanie „zakazanego wizerunku dziecka” jest przestępstwem zagrożonym karą do trzech lat pozbawienia wolności na podstawie sekcji 62 ustawy Coroners and Justice Act 2009, sformułowanej tak, by obejmowała obrazy rysowane i animowane. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "US": """Stany Zjednoczone. Prawo autorskie: nie ma wyjątku dla użytku prywatnego; osobiste, niekomercyjne tłumaczenie, które widzi tylko sam użytkownik, byłoby oceniane na podstawie fair use, czego w takiej sytuacji nie rozstrzygnął żaden sąd. Czy przechwytywanie ekranu, który czytnik zgodnie z prawem wyświetlił, „obchodzi” zabezpieczenie w rozumieniu sekcji 1201 DMCA, jest kwestią sporną, w której padają argumenty w obie strony, i pozostaje nierozstrzygnięte; TASlation jedynie odczytuje ekran. Naruszenie jest sprawą cywilnoprawną, chyba że jest umyślne i popełnione w celu osiągnięcia korzyści majątkowej lub na dużą skalę. Treści: 18 U.S.C. § 1466A czyni posiadanie obscenicznych rysunków, kreskówek lub obrazów przedstawiających małoletnich podczas czynności seksualnych przestępstwem federalnym; kolekcjoner japońskiej mangi przyznał się na tej podstawie do winy w 2009 r. i orzeczono przepadek jego książek. Obowiązują też stanowe przepisy o obsceniczności.""",
    "CA": """Kanada. Prawo autorskie: sekcja 29.22 ustawy o prawie autorskim pozwala zwielokrotniać do celów prywatnych utwór, którego legalny egzemplarz się posiada, o ile nie obchodzi się żadnej blokady cyfrowej i nie przekazuje się nikomu kopii; przepis obejmuje tylko zwielokrotnianie, więc tłumaczenie na własny użytek się w nim nie mieści i stanowi w świetle prawa naruszenie o charakterze cywilnoprawnym, bez szkody, której można by dochodzić, gdy niczego się nie udostępnia. Treści: sekcja 163.1 kodeksu karnego definiuje pornografię dziecięcą jako każde przedstawienie wizualne, a Sąd Najwyższy orzekł w sprawie R. v. Sharpe, że „osoba” obejmuje osoby wyimaginowane, więc materiały rysunkowe są objęte przepisem; za posiadanie przewidziano minimalny wymiar kary pozbawienia wolności. Funkcjonariusze służb granicznych przeglądają urządzenia i postawili podróżnemu zarzuty z powodu mangi na laptopie. Nie należy przewozić niczego, co do czego nie ma się pewności.""",
    "AU": """Australia. Prawo autorskie: sekcja 43C ustawy o prawie autorskim pozwala jednokrotnie skopiować posiadaną książkę do innego formatu na użytek prywatny; nie ma ogólnego wyjątku dla użytku prywatnego, a tłumaczenie na własny użytek jest opracowaniem, którego nie obejmuje żaden wyjątek, więc stanowi w świetle prawa naruszenie o charakterze cywilnoprawnym. Treści: federalny kodeks karny i ustawy stanowe o materiałach przedstawiających wykorzystywanie dzieci obejmują materiały rysunkowe i animowane, ponieważ w sprawie McEwen v Simmons (NSW, 2008) orzeczono, że postać z kreskówki może być „osobą”; posiadanie jest poważnym przestępstwem. Tytułów, którym odmówiono klasyfikacji, nie wolno sprzedawać ani importować, w niektórych stanach ich posiadanie jest przestępstwem, a funkcjonariusze służb granicznych mogą przeglądać urządzenia, z którymi się podróżuje. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "NZ": """Nowa Zelandia. Prawo autorskie: nie ma ogólnego wyjątku dla użytku prywatnego; wyjątek dotyczący zmiany formatu obejmuje tylko nagrania dźwiękowe, a tłumaczenie na własny użytek nie jest objęte wyjątkiem, więc stanowi w świetle prawa naruszenie o charakterze cywilnoprawnym. Treści: na podstawie ustawy Films, Videos, and Publications Classification Act publikacja, w tym rysunki i manga, może być „niedopuszczalna” (objectionable), a świadome posiadanie niedopuszczalnej publikacji jest przestępstwem zagrożonym karą do dziesięciu lat pozbawienia wolności; wszczynano postępowania karne w związku z mangą hentai. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "IE": """Irlandia. Prawo autorskie: nie ma wyjątku dla kopii prywatnej; najbliższym przepisem jest fair dealing do celów badań lub prywatnej nauki, który nie dotyczy czytania dla przyjemności, więc tłumaczenie na własny użytek stanowi w świetle prawa naruszenie o charakterze cywilnoprawnym. Treści: ustawa Child Trafficking and Pornography Act 1998 definiuje pornografię dziecięcą jako każde przedstawienie wizualne osoby, która jest dzieckiem lub wygląda na dziecko, przy czym wyraźnie obejmuje postacie rysowane, jeśli przeważa wrażenie, że jest to dziecko; świadome posiadanie jest przestępstwem zagrożonym karą do pięciu lat pozbawienia wolności. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "DE": """Niemcy. Prawo autorskie: § 53 UrhG pozwala osobie fizycznej sporządzać kopie na użytek prywatny ze źródła, które nie jest w oczywisty sposób bezprawne, a § 23 pozwala swobodnie sporządzić opracowanie, takie jak tłumaczenie; zgody autora wymaga dopiero jego publikacja lub eksploatacja. Czytanie za pomocą TASlation na własny użytek ma więc solidne podstawy, o ile nie obchodzi się żadnego technicznego zabezpieczenia (§ 95a), czego TASlation nie robi. Treści: § 184b StGB penalizuje posiadanie przedstawień seksualnego wykorzystywania dzieci, które odtwarzają rzeczywiste lub realistyczne („wirklichkeitsnahes”) zdarzenie; wyraźnie fikcyjne rysunki zwykle nie są nim objęte, realistyczne tak, a §§ 184c i 184 dotyczą młodzieży i innej pornografii.""",
    "AT": """Austria. Prawo autorskie: § 42 UrhG pozwala osobie fizycznej sporządzać kopie utworu na użytek prywatny; sporządzenie tłumaczenia dla siebie nie jest nim wyraźnie objęte, ale prawo austriackie, podobnie jak niemieckie, wymaga zgody autora na eksploatację opracowania, a nie na jego sporządzenie. Treści: § 207a StGB penalizuje posiadanie seksualnych przedstawień małoletnich, a ponieważ jego brzmienie obejmuje przedstawienia „realistyczne” („wirklichkeitsnahe”), realistyczne rysunki są nim objęte, a wyraźnie fikcyjne zwykle nie.""",
    "CH": """Szwajcaria. Prawo autorskie: art. 19 ustawy o prawie autorskim dopuszcza każde korzystanie z opublikowanego utworu w sferze prywatnej, w tym tłumaczenie go dla siebie, o ile nie obchodzi się żadnego technicznego zabezpieczenia. Treści: art. 197 kodeksu karnego zalicza przedstawienia czynności seksualnych z małoletnimi, które nigdy nie miały miejsca, w tym rysowane i animowane, do twardej pornografii, a ich posiadanie na własny użytek jest karalne, chyba że dzieło ma wartość kulturalną lub naukową zasługującą na ochronę. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "FR": """Francja. Prawo autorskie: art. L122-5 kodeksu własności intelektualnej dopuszcza kopie prywatne z legalnego źródła, ale art. L122-4 czyni bezprawnym każde tłumaczenie bez zgody autora, nawet takie, którego nikt nie widzi; jest to sprawa cywilnoprawna bez szkody, której można by dochodzić, dopóki niczego się nie udostępnia. Treści: art. 227-23 kodeksu karnego penalizuje posiadanie pornograficznych obrazów lub „przedstawień” małoletnich, a rząd oświadczył, że rysunek jest przedstawieniem; od 2013 r. przepis obejmuje także obrazy osób, których wygląd fizyczny jest wyglądem małoletniego. Ściganie z powodu mangi jest rzadkie, ale przepis na nie pozwala.""",
    "BE": """Belgia. Prawo autorskie: kodeks prawa gospodarczego dopuszcza kopię prywatną w kręgu rodzinnym (art. XI.190); czy obejmuje to tłumaczenie na własny użytek, nie zostało rozstrzygnięte, należy więc traktować je raczej jako tolerowane niż dozwolone i nigdy go nie udostępniać. Treści: kodeks karny (art. 417/13, dawniej 383bis) penalizuje świadome posiadanie materiałów wizualnie przedstawiających małoletniego lub osobę, która wygląda na małoletnią, podczas zachowań seksualnych, rzeczywistych lub symulowanych; policja oświadczyła, że manga może być objęta tym przepisem, nawet jeśli nie dotyczy żadnego rzeczywistego małoletniego. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "NL": """Niderlandy. Prawo autorskie: art. 16b ustawy o prawie autorskim dopuszcza kopię z legalnego źródła do własnych ćwiczeń, nauki lub użytku, a ponieważ ustawa uznaje tłumaczenie za zwielokrotnienie (art. 13), objęte jest również tłumaczenie na własny użytek. Treści: kodeks karny (art. 240b, przeniesiony do art. 252) penalizuje posiadanie wirtualnej pornografii dziecięcej, jeśli jest realistyczna; rysunki i animacje nie są objęte tym przepisem, chyba że niemal nie da się ich odróżnić od obrazów rzeczywistego dziecka, a sądy nie wyznaczyły tej granicy w sposób spójny. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "ES": """Hiszpania. Prawo autorskie: art. 31.2 ustawy o własności intelektualnej dopuszcza kopię prywatną z legalnego źródła (rekompensowaną opłatą reprograficzną), ale dla przekształcenia, które obejmuje tłumaczenie (art. 21), nie przewidziano wyjątku dla użytku prywatnego, więc tłumaczenie na własny użytek stanowi w świetle prawa naruszenie o charakterze cywilnoprawnym. Treści: art. 189 kodeksu karnego penalizuje posiadanie pornografii dziecięcej, której definicja obejmuje „realistyczne obrazy” małoletniego; okólnik prokuratury 2/2015 stwierdza, że kreskówki i manga nie są realistycznymi obrazami i nie są objęte przepisem, natomiast realistyczne rysunki i obrazy osób wyglądających na małoletnie nadal są nim objęte.""",
    "MX": """Meksyk. Prawo autorskie: art. 148 pkt IV federalnej ustawy o prawie autorskim dopuszcza jedną kopię utworu do osobistego i prywatnego użytku osoby, która ją sporządza, bez celu zarobkowego; tłumaczenie nie jest nim objęte, więc tłumaczenie na własny użytek stanowi w świetle prawa naruszenie, sprawę cywilnoprawną, gdy niczego się nie udostępnia. Treści: art. 202 federalnego kodeksu karnego penalizuje posiadanie pornografii dziecięcej; przepis sformułowano z myślą o rzeczywistych osobach poniżej osiemnastu lat, a materiały rysunkowe nie są nim wyraźnie objęte.""",
    "AR": """Argentyna. Prawo autorskie: ustawa 11.723 nie przewiduje wyjątku dla kopii prywatnej, więc nawet tłumaczenie na własny użytek stanowi w świetle prawa naruszenie; jest to sprawa cywilnoprawna, dopóki niczego się nie udostępnia. Treści: art. 128 kodeksu karnego, znowelizowany w 2018 r., karze samo posiadanie seksualnych „przedstawień” osób poniżej osiemnastu lat; to, czy rysunek jest takim przedstawieniem, jest sporne wśród prawników i żaden sąd tego nie rozstrzygnął, więc materiały rysunkowe należy traktować jako ryzyko.""",
    "BR": """Brazylia. Prawo autorskie: ustawa 9.610 dopuszcza jedynie zwielokrotnianie krótkich fragmentów na prywatny użytek kopiującego (art. 46 II); tłumaczenie na własny użytek stanowi w świetle prawa naruszenie, sprawę cywilnoprawną, gdy niczego się nie udostępnia. Treści: Statut Dziecka i Nastolatka (art. 241-B i 241-C) penalizuje posiadanie scen seksualnych z udziałem dzieci lub nastolatków, w tym symulowanych przez przerobienie lub montaż „jakiejkolwiek innej formy przedstawienia wizualnego”, co prawnicy odczytują jako obejmujące rysunki; sądy nie rozstrzygnęły tej kwestii w odniesieniu do mangi.""",
    "PT": """Portugalia. Prawo autorskie: art. 75 ust. 2 lit. a kodeksu prawa autorskiego dopuszcza zwielokrotnianie na użytek prywatny (rekompensowane opłatą reprograficzną); tłumaczenie jest odrębnym prawem bez wyjątku dla użytku prywatnego, więc tłumaczenie na własny użytek stanowi w świetle prawa naruszenie o charakterze cywilnoprawnym. Treści: art. 176 kodeksu karnego penalizuje posiadanie materiałów pornograficznych z „realistycznym przedstawieniem” małoletniego; stylizowane rysunki zwykle nie są nim objęte, realistyczne tak, a granica jest sporna.""",
    "IT": """Włochy. Prawo autorskie: wyjątek dla kopii prywatnej (art. 71-sexies ustawy 633/1941) obejmuje tylko nagrania dźwiękowe i wideo, a tłumaczenie jest prawem wyłącznym bez wyjątku dla użytku prywatnego, więc tłumaczenie na własny użytek stanowi w świetle prawa naruszenie o charakterze cywilnoprawnym. Treści: art. 600-quater.1 kodeksu karnego rozszerza przestępstwo posiadania na obrazy „wirtualne”, które sprawiają, że nierzeczywiste sytuacje wydają się prawdziwe; rysunki długo uznawano za nieobjęte tym przepisem, ale Sąd Kasacyjny rozszerzył w 2025 r. to pojęcie na obrazy powstałe w wyniku obróbki graficznej bez związku z rzeczywistymi sytuacjami, a kolekcjoner komiksów był ścigany karnie. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "PL": """Polska. Prawo autorskie: art. 23 ustawy o prawie autorskim pozwala korzystać z rozpowszechnionego utworu w zakresie własnego użytku osobistego, a zakres ten jest szeroki; tłumaczenie zachowane dla siebie zwykle uznaje się za mieszczące się w nim, a jego udostępnianie już nie. Treści: art. 202 § 4b kodeksu karnego penalizuje posiadanie treści pornograficznych przedstawiających „wytworzony albo przetworzony wizerunek” małoletniego; to, czy rysunek jest takim wizerunkiem, jest sporne, a rysunki realistyczne z większym prawdopodobieństwem zostaną za taki wizerunek uznane.""",
    "RU": """Rosja. Prawo autorskie: art. 1273 kodeksu cywilnego dopuszcza zwielokrotnianie do celów osobistych; tłumaczenie jest odrębnym prawem bez wyjątku dla użytku osobistego, więc tłumaczenie na własny użytek nie jest wyraźnie dozwolone, a gdy niczego się nie udostępnia, jest to sprawa cywilnoprawna. Treści: art. 242.1 kodeksu karnego karze wytwarzanie, przechowywanie i przemieszczanie pornograficznych przedstawień małoletnich tylko wtedy, gdy odbywa się to w celu rozpowszechniania, więc samo prywatne przechowywanie nie stanowi tego przestępstwa, a to, czy przedstawienia rysunkowe lub animowane się liczą, nie zostało rozstrzygnięte; art. 242 dotyczy innej pornografii, gdy jest rozpowszechniana.""",
    "TR": """Turcja. Prawo autorskie: art. 38 ustawy o utworach intelektualnych i artystycznych dopuszcza zwielokrotnianie utworu na użytek osobisty bez celu handlowego; tłumaczenie jest odrębnym prawem bez wyjątku dla użytku osobistego, więc tłumaczenie na własny użytek nie jest wyraźnie dozwolone, a gdy niczego się nie udostępnia, jest to sprawa cywilnoprawna. Treści: art. 226 ust. 3 kodeksu karnego karze posiadanie lub przechowywanie obscenicznych obrazów z wykorzystaniem dzieci lub osób wyglądających jak dzieci, a praktycy prawa odczytują go jako obejmujący przedstawienia rysunkowe i animowane; posiadanie jest zagrożone karą od dwóch do pięciu lat pozbawienia wolności. Prywatne posiadanie obscenicznych materiałów z udziałem wyłącznie dorosłych nie jest przestępstwem.""",
    "ID": """Indonezja. Prawo autorskie: art. 46 ustawy o prawie autorskim dopuszcza jedną kopię opublikowanego utworu na użytek osobisty; tłumaczenie nie jest nim objęte, więc tłumaczenie na własny użytek nie jest wyraźnie dozwolone, a gdy niczego się nie udostępnia, jest to sprawa cywilnoprawna. Treści: ustawa o pornografii (44/2008) definiuje pornografię tak, że obejmuje ona kreskówki i animacje, oraz zakazuje jej posiadania, ale objaśnienia do niej wyłączają posiadanie dla siebie i we własnym interesie; rozpowszechnianie, także w internecie na podstawie ustawy ITE, jest przestępstwem. Nie należy przechowywać niczego, co do czego nie ma się pewności, ani niczego udostępniać.""",
    "VN": """Wietnam. Prawo autorskie: art. 25 ustawy o własności intelektualnej pozwala sporządzić jedną kopię do własnych badań naukowych lub nauki, a nie do czytania dla przyjemności, i nie obejmuje tłumaczenia; tłumaczenie na własny użytek nie jest wyraźnie dozwolone, a gdy niczego się nie udostępnia, jest to sprawa cywilnoprawna. Treści: art. 326 kodeksu karnego karze wytwarzanie, kopiowanie, przewożenie lub przechowywanie materiałów „deprawujących” w celu ich rozpowszechniania, przy czym wymiar kary zależy od ilości materiałów; samo przechowywanie dla siebie nie stanowi tego przestępstwa, ale przewidziano za nie kary administracyjne, a o tym, co jest deprawujące, decydują władze. Nie należy niczego udostępniać.""",
    "CN": """Chiny. Prawo autorskie: art. 24 pkt 1 ustawy o prawie autorskim dopuszcza korzystanie z opublikowanego utworu w celu osobistej nauki, badań lub przyjemności, co rozumie się jako obejmujące tłumaczenie go dla siebie. Treści: kodeks karny (art. 363–367) karze wytwarzanie, sprzedaż lub rozpowszechnianie materiałów obscenicznych, w tym komiksów, a ustawa o karach administracyjnych w zakresie bezpieczeństwa publicznego karze rozpowszechnianie; samo prywatne posiadanie nie jest czynem zabronionym, ale wszystko, co się udostępnia lub publikuje, już tak.""",
    "TW": """Tajwan. Prawo autorskie: art. 51 ustawy o prawie autorskim dopuszcza zwielokrotnianie na użytek osobisty lub rodzinny bez celu zarobkowego, a art. 63 pozwala w tym celu przetłumaczyć utwór. Treści: ustawa o zapobieganiu seksualnemu wykorzystywaniu dzieci i młodzieży penalizuje posiadanie seksualnych wizerunków dzieci i młodzieży, w tym wytworzonych komputerowo, które wyglądają jak prawdziwe; czy objęte są materiały czysto rysunkowe lub animowane, jest sporne i nie zostało rozstrzygnięte przez sądy.""",
    "HK": """Hongkong. Prawo autorskie: nie ma wyjątku dla kopii prywatnej; najbliższym przepisem jest fair dealing do celów badań lub prywatnej nauki, a tłumaczenie na własny użytek jest opracowaniem, którego nie obejmuje żaden wyjątek, więc stanowi w świetle prawa naruszenie o charakterze cywilnoprawnym. Treści: rozporządzenie Prevention of Child Pornography Ordinance (Cap. 579) penalizuje posiadanie wizualnego przedstawienia, które w sposób seksualny ukazuje osobę mającą mniej niż szesnaście lat lub przedstawioną jako mającą mniej niż szesnaście lat, w tym rysunków, przy czym przewiduje obronę opartą na wartości artystycznej; inne materiały reguluje rozporządzenie Control of Obscene and Indecent Articles Ordinance.""",
    "SG": """Singapur. Prawo autorskie: ustawa o prawie autorskim z 2021 r. nie przewiduje wyjątku dla kopii prywatnej książek; tłumaczenie na własny użytek byłoby oceniane na podstawie zawartego w niej przepisu o fair use, którego żaden sąd nie zastosował do takiej sytuacji, więc może ono stanowić w świetle prawa naruszenie o charakterze cywilnoprawnym. Treści: kodeks karny (sekcja 377BK) czyni posiadanie materiałów przedstawiających wykorzystywanie dzieci przestępstwem zagrożonym karą do pięciu lat pozbawienia wolności, a materiały te obejmują rysunkowe przedstawienia osoby, która rozsądnemu obserwatorowi wydaje się mieć mniej niż szesnaście lat; ustawy Undesirable Publications Act i Films Act czynią obsceniczne publikacje i filmy przestępstwem nawet przy prywatnym posiadaniu. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "PH": """Filipiny. Prawo autorskie: sekcja 187 kodeksu własności intelektualnej dopuszcza jedną kopię prywatną do celów badań i prywatnej nauki, a nie do czytania dla przyjemności, i nie obejmuje tłumaczenia; tłumaczenie na własny użytek nie jest wyraźnie dozwolone, a gdy niczego się nie udostępnia, jest to sprawa cywilnoprawna. Treści: ustawa Republic Act 11930 (2022, zastępująca Anti-Child Pornography Act) definiuje „dziecko” jako obejmujące obrazy wygenerowane komputerowo, wykonane cyfrowo lub ręcznie tak, by wyglądały jak dziecko, i czyni posiadanie przestępstwem; domniemywa się, że posiadanie trzech lub więcej sztuk służy rozpowszechnianiu. Nie należy przechowywać niczego, co do czego nie ma się pewności.""",
    "KR": """Korea Południowa. Prawo autorskie: art. 30 ustawy o prawie autorskim dopuszcza zwielokrotnianie na użytek prywatny, a art. 36 pozwala w tym celu przetłumaczyć utwór. Treści: ustawa o ochronie dzieci i młodzieży przed przestępstwami seksualnymi traktuje seksualne przedstawienia osób lub wyobrażeń, które można wyraźnie rozpoznać jako dzieci lub młodzież, w tym animacje i mangę, jako materiały przedstawiające seksualne wykorzystywanie dzieci lub młodzieży, a ich kupowanie, posiadanie lub oglądanie jest przestępstwem; nowelizacja z 2025 r. zniosła konieczność udowodnienia, że sprawca o tym wiedział.""",
}
